// n8n Cloud has no env variables: set the staff email here
const STAFF_EMAIL = 'staff@example.com';

// Trusted menu = rows of the menu_items Data Table (never the browser's prices)
const rows = $('Get Menu Items').all().map(i => i.json);
const MENU = {};
for (const r of rows) {
  if (!r || typeof r.itemId !== 'string' || r.itemId === '') continue;
  if (r.active === false || r.active === 'false') continue;
  const price = Number(r.price);
  if (!Number.isFinite(price) || price < 0) continue;
  MENU[r.itemId] = { name: String(r.name), price };
}

const body = $('Order Webhook').first().json.body || {};
const customer = body.customer || {};
const items = Array.isArray(body.items) ? body.items : [];
const errors = [];

if (Object.keys(MENU).length === 0) errors.push('Menu is currently unavailable. Please try again later.');

const name = String(customer.name || '').trim();
const email = String(customer.email || '').trim();
const phone = String(customer.phone || '').replace(/[\s-]/g, '');

if (name.length < 2 || name.length > 80) errors.push('Customer name is required (2-80 characters).');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('A valid email address is required.');
if (!/^\+?\d{10,13}$/.test(phone)) errors.push('A valid phone number is required (10-13 digits).');
if (items.length === 0) errors.push('Cart is empty.');
if (items.length > 30) errors.push('Too many items in cart.');

const lines = [];
for (const it of items.slice(0, 30)) {
  const id = it && it.id;
  const qty = Number(it && it.quantity);
  if (typeof id !== 'string' || !Object.prototype.hasOwnProperty.call(MENU, id)) {
    errors.push('Unknown or unavailable product id: ' + String(id));
    continue;
  }
  const m = MENU[id];
  if (!Number.isInteger(qty) || qty < 1 || qty > 20) {
    errors.push('Invalid quantity for ' + m.name + ' (1-20 allowed).');
    continue;
  }
  lines.push({ id, name: m.name, quantity: qty, unitPrice: m.price, lineTotal: m.price * qty });
}

if (errors.length > 0) {
  return [{ json: { valid: false, errors } }];
}

const total = lines.reduce((s, l) => s + l.lineTotal, 0);
const year = new Date().getFullYear();
const orderId = 'BC-' + year + '-' + Date.now().toString(36).slice(-5).toUpperCase() +
  Math.random().toString(36).slice(2, 4).toUpperCase();

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const rowsHtml = lines.map(l =>
  '<tr><td style="padding:8px;border-bottom:1px solid #eee">' + esc(l.name) + '</td>' +
  '<td style="padding:8px;border-bottom:1px solid #eee;text-align:center">' + l.quantity + '</td>' +
  '<td style="padding:8px;border-bottom:1px solid #eee;text-align:right">&#8377;' + l.lineTotal + '</td></tr>'
).join('');

const emailHtml =
  '<div style="font-family:Arial,sans-serif;max-width:560px;margin:auto;color:#3b2a20">' +
  '<h2 style="color:#6f4e37">Brew Cup Cafe</h2>' +
  '<p>Hi ' + esc(name) + ', thank you for your order!</p>' +
  '<p><b>Order ID:</b> ' + orderId + '</p>' +
  '<table style="width:100%;border-collapse:collapse"><tr style="background:#f5ebe0"><th style="padding:8px;text-align:left">Item</th><th style="padding:8px">Qty</th><th style="padding:8px;text-align:right">Amount</th></tr>' +
  rowsHtml +
  '<tr><td colspan="2" style="padding:8px;text-align:right"><b>Total</b></td><td style="padding:8px;text-align:right"><b>&#8377;' + total + '</b></td></tr></table>' +
  '<p style="font-size:12px;color:#888">Sample order for the Brew Cup Cafe capstone demo.</p></div>';

const staffHtml =
  '<div style="font-family:Arial,sans-serif"><h3>New order ' + orderId + '</h3>' +
  '<p>Customer: ' + esc(name) + '<br>Phone: ' + esc(phone) + '<br>Email: ' + esc(email) + '</p>' +
  '<table style="border-collapse:collapse">' + rowsHtml + '</table><p><b>Total: &#8377;' + total + '</b></p></div>';

return [{ json: {
  valid: true, orderId, total, lines, staffEmail: STAFF_EMAIL,
  customer: { name, email, phone },
  emailSubject: 'Brew Cup Cafe - Order ' + orderId + ' confirmed',
  staffSubject: 'New order ' + orderId + ' (Rs.' + total + ')',
  emailHtml, staffHtml
} }];
